// ─── Toy-box repaints of the boss badges, level-up arrow and movie icon ─────
//
// PAINTED_BADGE_ICONS (generated by tools/badge-icons/pack.mjs) lists the
// repaints that ship. Each lookup returns the repaint's path when it is listed,
// else the OLD file (the procedural boss crest bake, the old stat-sheet arrow,
// the grey movie icon) — so every consumer keeps working before / without the
// paint pass, and no request is made for an unlisted file. `?art=procedural`
// (A/B) always returns the old file.
import { PAINTED_BADGE_ICONS, type BadgeIconName } from '@/use/paintedBadgeIcons'
import { prependBaseUrl } from '@/utils/function'

const artAllowed = (): boolean =>
  typeof location === 'undefined' || !/[?&]art=procedural(?:&|$)/.test(location.search)

/** Path under public/ of the icon: the listed repaint (cache-keyed), else `fallback`. */
export const badgeIconPath = (name: BadgeIconName, fallback: string): string => {
  const p = PAINTED_BADGE_ICONS[name]
  return p && artAllowed() ? `${p.file}?v=${p.v}` : fallback
}

export const MOVIE_ICON_FALLBACK = 'images/icons/movie_128x96.webp'

/** The rewarded-ad movie icon (128 × 96 box), path under public/. */
export const movieIconPath = (): string => badgeIconPath('movie', MOVIE_ICON_FALLBACK)

/** The rewarded-ad movie icon URL (base-prefixed). */
export const movieIconSrc = (): string => prependBaseUrl(movieIconPath())
